import {days,schedules,time,active,parsePages} from './core.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let plan,blob,db,pending,mode='normal',last='';
try{mode=localStorage.getItem('schedule-mode')==='short'?'short':'normal'}catch{}
const berlin=()=>{const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',weekday:'long',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const p=Object.fromEntries(parts.map(p=>[p.type,p.value]));return {day:['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].indexOf(p.weekday),minute:+p.hour*60+(+p.minute),clock:`${p.hour}:${p.minute}:${p.second}`}};
function render(){if(!plan)return;const now=berlin();$('clock').textContent=now.clock;const manual=$('manual').checked;const d=manual?+$('day').value:now.day;const minute=manual?$('when').value.split(':').reduce((a,v)=>a*60+(+v),0):now.minute;const h=active(d,minute,mode);const key=JSON.stringify([d,minute,h,mode,manual,plan.name]);if(key===last)return;last=key;
 $('normal').classList.toggle('selected',mode==='normal');$('short').classList.toggle('selected',mode==='short');$('normal').setAttribute('aria-pressed',mode==='normal');$('short').setAttribute('aria-pressed',mode==='short');$('custom').hidden=!manual;$('badge').textContent=manual?'VORSCHAU':'LIVE-ANSICHT';
 $('dateline').textContent=`${days[d]||['Samstag','Sonntag'][d-5]} · ${time(minute)} UHR · ${mode==='short'?'KURZSTUNDEN':'REGELSTUNDEN'}`;
 const cell=h>=0?plan.cells[d][h]:{entries:[],note:''};$('count').textContent=cell.entries.length;
 const next=d<5?schedules[mode].findIndex(([s])=>s>minute):-1;
 $('state').textContent=h>=0?`${h+1}. Stunde`:(d>4?'Wochenende':minute<480?'Vor Unterrichtsbeginn':next>=0?'Gerade ist Pause':'Unterricht beendet');
 $('stateDetail').textContent=h>=0?`${time(schedules[mode][h][0])} – ${time(schedules[mode][h][1])} Uhr · noch ${schedules[mode][h][1]-minute} Min.`:next>=0?`Nächste Stunde: ${next+1}. Stunde ab ${time(schedules[mode][next][0])} Uhr.`:'Außerhalb der Unterrichtszeiten sind keine Verfügbarkeiten hinterlegt.';
 $('resultsTitle').textContent=manual?'Lehrkräfte zum gewählten Zeitpunkt':'Jetzt laut Plan verfügbar';
 $('cards').innerHTML=cell.entries.length?cell.entries.map(e=>`<article class="card"><div class="cardtop"><div class="avatar">${esc(e.name)}</div><div><h3>${esc(e.name)}</h3><small>Lehrkraft · Kürzel laut Plan</small></div></div><div class="roomrow"><span>Gruppe <b>${esc(e.group||'–')}</b></span><span>Raum <b>${esc(e.room||'–')}</b></span></div>${(!e.group||!e.room||e.room==='UG')?'<p class="muted" style="font-size:11px;margin-bottom:0">Angabe in der PDF unvollständig.</p>':''}</article>`).join(''):`<div class="empty"><strong>${h>=0?'Keine festen Einträge für diese Stunde.':'Aktuell keine Unterrichtsstunde.'}</strong>${h>=0?'Bitte beachten Sie mögliche Sonderregelungen unten.':'Über „Zeitpunkt auswählen“ können Sie den Plan für eine andere Zeit ansehen.'}</div>`;
 $('note').hidden=!cell.note.trim();$('note').innerHTML='<b>Hinweise & Rücksprache</b>'+esc(cell.note.trim());
 $('timeline').innerHTML=schedules[mode].map(([s,e],i)=>`<button class="slot ${h===i?'current':''}" data-hour="${i}"><strong>${i+1}. Std.</strong><span>${time(s)} – ${time(e)}</span><em>${d<5?plan.cells[d][i].entries.length+' eingetragen':'Kein Schultag'}</em></button>`).join('');
 $('source').textContent=plan.name;
}
$('day').innerHTML=[...days,'Samstag','Sonntag'].map((d,i)=>`<option value="${i}">${d}</option>`).join('');$('day').value=Math.min(berlin().day,4);
for(const m of ['normal','short'])$(m).onclick=()=>{mode=m;try{localStorage.setItem('schedule-mode',m)}catch{}render()};
$('manual').onchange=()=>{if($('manual').checked){const n=berlin();$('day').value=n.day;$('when').value=time(n.minute)}render()};$('day').onchange=render;$('when').oninput=()=>{if($('when').value)render()};
$('timeline').onclick=e=>{const b=e.target.closest('[data-hour]');if(!b)return;const now=berlin();if(!$('manual').checked)$('day').value=Math.min(now.day,4);$('manual').checked=true;$('when').value=time(schedules[mode][+b.dataset.hour][0]);render()};
function openPdf(b){const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('view').onclick=()=>openPdf(blob);$('manage').onclick=()=>$('dialog').showModal();$('close').onclick=()=>$('dialog').close();$('previewPdf').onclick=()=>pending&&openPdf(pending.blob);
function editors(){let html='';for(let d=0;d<5;d++)for(let h=0;h<7;h++){const c=pending.plan.cells[d][h];html+=`<details class="editor"><summary>${days[d]} · ${h+1}. Stunde · ${c.entries.length} Einträge${c.note?' · Hinweis':''}</summary><label>Lehrkräfte (Kürzel | Gruppe | Raum)<textarea data-day="${d}" data-hour="${h}" data-kind="entries">${esc(c.entries.map(e=>`${e.name} | ${e.group} | ${e.room}`).join('\n'))}</textarea></label><label>Hinweise / Sonderregelung<textarea data-day="${d}" data-hour="${h}" data-kind="note">${esc(c.note.trim())}</textarea></label></details>`}$('editors').innerHTML=html;}
let uploadSequence=0;
$('file').onchange=async()=>{const file=$('file').files[0];const sequence=++uploadSequence;pending=null;$('review').hidden=true;$('confirmed').checked=false;$('save').disabled=true;if(!file)return;if(file.size>20*1024*1024){$('message').textContent='Bitte eine PDF unter 20 MB auswählen.';return}$('message').textContent='PDF wird gelesen …';let doc,loadingTask;
 try{const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;loadingTask=pdfjs.getDocument({data:await file.arrayBuffer(),isEvalSupported:false});doc=await loadingTask.promise;if(doc.numPages>20)throw Error('Bitte einen Plan mit höchstens 20 Seiten auswählen.');const pages=[];for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i);const v=page.getViewport({scale:1});const content=await page.getTextContent();pages.push(content.items.filter(t=>t.str?.trim()).map(t=>({str:t.str,x:t.transform[4]/v.width,y:(v.height-t.transform[5])/v.width})).map(t=>({str:t.str,x:t.x*842,y:t.y*842})));}const cells=parsePages(pages);if(sequence!==uploadSequence)return;pending={plan:{name:file.name,cells},blob:file};editors();$('review').hidden=false;$('message').textContent=`${cells.flat().reduce((n,c)=>n+c.entries.length,0)} Einträge erkannt. Bitte alle 35 Zeitfelder und Sonderhinweise prüfen, bevor Sie den Plan übernehmen.`;
 }catch(e){if(sequence===uploadSequence)$('message').textContent='Import nicht übernommen: '+(e.message||'PDF konnte nicht gelesen werden.')}finally{if(loadingTask)await loadingTask.destroy();}
};
$('confirmed').onchange=()=>$('save').disabled=!$('confirmed').checked;$('editors').oninput=()=>{$('confirmed').checked=false;$('save').disabled=true};
$('save').onclick=async()=>{if(!pending||!$('confirmed').checked)return;try{const cells=structuredClone(pending.plan.cells);for(const input of $('editors').querySelectorAll('textarea')){const c=cells[+input.dataset.day][+input.dataset.hour];if(input.dataset.kind==='note'){c.note=input.value.trim();continue}c.entries=input.value.split('\n').filter(s=>s.trim()).map(line=>{const p=line.split('|').map(s=>s.trim());if(p.length!==3||!p[0])throw Error(`${days[+input.dataset.day]}, Stunde ${+input.dataset.hour+1}: Bitte „Kürzel | Gruppe | Raum“ verwenden.`);return {name:p[0],group:p[1],room:p[2]}})}const updated={plan:{...pending.plan,cells},blob:pending.blob};if(!db)throw Error('Dauerhaftes Speichern ist in diesem Browser nicht verfügbar. Bitte den Browser-Speicher freigeben.');await new Promise((resolve,reject)=>{const tx=db.transaction('plans','readwrite');tx.objectStore('plans').put(updated,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Speichern abgebrochen'))});plan=updated.plan;blob=updated.blob;last='';render();$('dialog').close();$('message').textContent='Plan gespeichert.';}catch(e){$('message').textContent='Plan nicht übernommen: '+e.message;$('message').scrollIntoView({block:'nearest'});}};
try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('kollegium-jetzt',1);req.onupgradeneeded=()=>req.result.createObjectStore('plans');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const saved=await new Promise((resolve,reject)=>{const r=db.transaction('plans').objectStore('plans').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(saved){plan=saved.plan;blob=saved.blob}}catch{}
if(!plan){try{const [p,b]=await Promise.all([fetch('./initial.json'),fetch('./plan.pdf')]);if(!p.ok||!b.ok)throw Error();plan=await p.json();blob=await b.blob()}catch{$('state').textContent='Plan konnte nicht geladen werden';$('stateDetail').textContent='Bitte die Seite erneut laden.'}}
render();setInterval(render,1000);document.addEventListener('visibilitychange',()=>render());
